["message"] = "|cff979797|Hpratcopy|h[23:50:21]|h|r |cFFFCD6CD[23:50:21] |cFF00FF00[RareScanner]: |cFFFFFFFF|cff85c1e9|Haddon:RareScanner:1:233471:2346:0.57041394710541:0.79285609722137:1741751421|h[Event: Scrapchewer]|h|r found!",
["timestamp"] = 128044.196,
