18,
19,
["n"] = 3,
},
["timestamp"] = 128047.762,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[23:50:28]|h|r Grimla Fizzlecrank says: Plus it's hilarious to watch Gaz turn all mushy big brother-type whenever they spend time with each other.",
["serverTime"] = 1741751428,
