13,
18,
19,
["n"] = 3,
},
["timestamp"] = 128051.217,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[23:50:30]|h|r Marin Noggenfogger says: He used to be an apprentice of Monte's, you know. I'd suspect this all a scheme if I trusted the Bilgewater Trade-Prince any less.",
["serverTime"] = 1741751430,
["r"] = 1,
["extraData"] = {
13,
