19,
["n"] = 3,
},
["timestamp"] = 128052.991,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[23:50:31]|h|r Monte Gazlowe says: No opposition to Rosebud? Really? Is this the first time the cartels have agreed on something?!",
