},
{
["message"] = "|cff979797|Hpratcopy|h[23:50:37]|h|r Rosebud Gallywix says: Hiya! I'm Rosebud. Gaz gave me the skinny on you.",
["serverTime"] = 1741751437,
["r"] = 1,
