19,
["n"] = 3,
},
["timestamp"] = 128059.756,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[23:50:39]|h|r Monte Gazlowe says: That's great news. It means the ownership of the Gallagio will transfer with no problems at court tomorrow!",
["serverTime"] = 1741751439,
["r"] = 1,
