["serverTime"] = 1741751440,
},
{
["message"] = "|cff979797|Hpratcopy|h[23:50:41]|h|r Rosebud Gallywix says: Have you met my Chiefs? I wanna take good care of this place, and I can't do it without the support of a strong team.",
